    "info.correctThreadDiameter.title": "Correct Thread Diameter",
    "info.correctThreadDiameter.body": "SmiCut optically measures the pitch diameter of its thread mills and laser-marks the theoretical external diameter on each tool. Enter this marked value as the cutter diameter in SmiProg to help achieve the correct thread diameter from the first cut. If further adjustment is needed, adjust the value in SmiProg or the tool compensation in the control system.",
