    "tool.enterThreadLength": "Gänglängd",
    "tool.noMatchingTool": "Inget matchande verktyg hittades för den valda gängan och gänglängden.",
    "tool.customDimensions": "➜ Egna verktygsmått",
    "tool.custom": "Eget verktyg",
    "tool.linkText": "➜ Se verktygssidan för alla mått och en STEP-fil för 3D-CAD",
    "info.howToUse": "Så här använder du SmiProg",
    "info.step1.title": "Definiera gängan",
    "info.step1.body": "Välj material, gängprofil, gängdimension och gänglängd. Ange säkerhetsavstånd under CNC-program. För M-gängor anges stigningen i millimeter. Övriga profiler använder gängor per tum (TPI).",
    "info.step2.title": "Välj gängfräsen",
    "info.step2.body": "Välj en föreslagen gängfräs från SmiCut eller ange egna verktygsmått i verktygsvalet.",
    "info.step3.title": "Kontrollera resultatet",
    "info.step3.body": "Välj tillverkningsprocess, styrsystem och gängriktning under CNC-program. Kontrollera skärdata, bearbetningstid och CNC-program före bearbetning.",
    "info.beforeMachining.title": "Före bearbetning",
    "info.beforeMachining.body": "Kontrollera att gängfräsen klarar vald gängdiameter, stigning och gänglängd. Verifiera programmet i simulering eller med enkelblockskörning före produktion.",
    "info.figureAlt": "Måttskiss för gängfräsning med gängdiameter, stigning, gänglängd, skärlängd, säkerhetsavstånd och fräsdiameter.",
    "info.figure.threadDiameter": "Gängdiameter",
    "info.figure.pitch": "Stigning",
    "info.figure.threadLength": "Gänglängd",
    "info.figure.safetyDistance": "Säkerhetsavstånd",
    "info.figure.cutterDiameter": "Fräsdiameter",
    "info.figure.cuttingLength": "Skärlängd",
    "info.machiningNotes": "Bearbetningsanvisningar",
    "info.toolCompensation.title": "Verktygskompensering",
    "info.toolCompensation.body": "Med SmiProg används verktygskompenseringen endast för mindre justeringar. Det minskar risken för problem vid radiekompensering på korta förflyttningar. Ange därför ett värde nära noll för diameterkompenseringen i styrsystemets verktygsregister.",
    "info.correctThreadDiameter.title": "Rätt gängdiameter direkt",
    "info.correctThreadDiameter.body": "På gängfräsar från SmiCut är medeldiametern uppmätt optiskt och den teoretiska ytterdiametern lasermärkt på verktyget. Ange detta mått som fräsdiameter i SmiProg för att få rätt gängdiameter direkt. Om ytterligare justering behövs kan du ändra värdet i SmiProg eller verktygskompenseringen i styrsystemet.",
    "info.customTools.title": "Specialverktyg",
    "info.customTools.body": "Välj Egna verktygsmått om din fräs saknas i listan. Ange fräsdiameter, skärlängd och antal skär. Kontrollera CNC-programmet noggrant när du använder egna verktyg.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Ange den valda hårdmetallfräsens hela skärlängd i fältet för gänglängd. Med SmiCuts ThreadBurr fräses och gradas gängan i samma operation.",
    "info.threadBurr.link": "ThreadBurr – solida gängfräsar från SmiCut",
    "info.oneTwoRows.title": "Verktyg med en eller två tänder (axiellt)",
    "info.oneTwoRows.body": "När du väljer en standardfräs från SmiCut av typen NM med en eller två tänder axiellt skapar SmiProg automatiskt en spiralrörelse tills gängan är färdig. För att använda samma cykel med ett annat lämpligt verktyg anger du stigningen som skärkantlängd under Egna verktygsmått. Kontrollera att verktyget är lämpligt och verifiera CNC-programmet före bearbetning.",
    "info.flankInfeed.title": "Flankinmatning",
    "info.flankInfeed.body": "SmiProg använder flankinmatning vid flera radiella pass. Det minskar vibrationer och ger stabilare bearbetning.",
    "info.flankInfeed.link": "Vibrationsfri gängfräsning för bättre produktivitet och ekonomi",
    "info.shortCuttingLength.title": "Verktyg med midja",
    "info.shortCuttingLength.body": "Om verktygets skärkantlängd är kortare än gänglängden gör SmiProg gängan i flera axiella pass när verktygstypen tillåter det.",
    "info.inserts.title": "Vändskärsgängfräsar",
    "info.inserts.body": "Välj Egna verktygsmått och ange fräskroppens skärdiameter, vändskärets skärkantlängd och antal skär. Vid behov delas bearbetningen upp i flera axiella pass. Verifiera CNC-programmet före bearbetning.",
    "info.taperedThreads.title": "Koniska gängor",
    "info.taperedThreads.body": "För koniska gängfräsar anges skärdiametern vid den sista fullständiga gängtanden närmast skaftet. Gängdiametern i SmiProg ska därför avse den position där denna del av verktyget går i ingrepp.",
    "info.warning.title": "Varning",
    "info.warning.body": "Skärdata i SmiProg är rekommenderade startvärden. Arbetsmaterial, maskinstabilitet, uppspänning, verktygsinställning, kylning och spånavgång kan kräva justeringar. SmiCut ansvarar inte för skador som uppstår vid användning av programmets CNC-kod eller rekommenderade skärdata.",
    "materialSelector.welcomeTitle": "Vilket material ska du bearbeta?",
