    "compare.password": "Passwort",
    "compare.lockHelp": "Geben Sie Ihre eigenen Werkzeugpreise ein. SmiCut-Händler können bei SmiCut das Passwort für die Katalogpreise anfordern.",
    "compare.enterThreadLength": "Geben Sie die Gewindelänge ein, um Werkzeuge zu vergleichen.",
    "compare.result": "Ergebnis",
    "tool.enterThreadLength": "Gewindelänge",
    "tool.noMatchingTool": "Kein passendes Werkzeug für das ausgewählte Gewinde und die Gewindelänge gefunden.",
    "tool.customDimensions": "➜ Benutzerdefinierte Werkzeugabmessungen",
    "tool.custom": "Benutzerdefiniertes Werkzeug",
    "tool.linkText": "➜ Alle Abmessungen und 3D-STEP-Datei siehe Werkzeugseite",
    "info.howToUse": "So verwenden Sie SmiProg",
    "info.step1.title": "Definieren Sie das Gewinde",
    "info.step1.body": "Wählen Sie Werkstoff, Gewindeprofil, Gewindegröße und Gewindelänge. Geben Sie den Sicherheitsabstand unter CNC-Programm ein. Bei M-Gewinden wird die Steigung in Millimetern angegeben; andere Profile verwenden Gewindegänge pro Zoll (TPI).",
    "info.step2.title": "Wählen Sie den Gewindefräser",
    "info.step2.body": "Verwenden Sie einen vorgeschlagenen SmiCut-Fräser oder geben Sie benutzerdefinierte Werkzeugabmessungen in der Werkzeugauswahl ein.",
    "info.step3.title": "Ausgabe überprüfen",
    "info.step3.body": "Wählen Sie unter CNC-Programm das Bearbeitungsverfahren, die Steuerung und die Gewinderichtung. Prüfen Sie vor der Bearbeitung die Schnittdaten, die Bearbeitungszeit und das CNC-Programm.",
    "info.beforeMachining.title": "Vor der Bearbeitung",
    "info.beforeMachining.body": "Prüfen Sie, ob der gewählte Gewindefräser für Gewindedurchmesser, Steigung und Gewindelänge geeignet ist. Prüfen Sie das Programm vor der Serienfertigung in einer Simulation oder im Einzelsatzbetrieb.",
    "info.figureAlt": "Maßskizze zum Gewindefräsen mit Gewindedurchmesser, Steigung, Gewindelänge, Schneidenlänge, Sicherheitsabstand und Fräserdurchmesser.",
    "info.figure.threadDiameter": "Gewindedurchmesser",
    "info.figure.pitch": "Steigung",
    "info.figure.threadLength": "Gewindelänge",
    "info.figure.safetyDistance": "Sicherheitsabstand",
    "info.figure.cutterDiameter": "Fräserdurchmesser",
    "info.figure.cuttingLength": "Schneidenlänge",
    "info.machiningNotes": "Hinweise zur Bearbeitung",
    "info.toolCompensation.title": "Werkzeug-Kompensation",
    "info.toolCompensation.body": "In SmiProg wird die Werkzeug-Kompensation nur für kleinere Korrekturen verwendet. Dies verringert Probleme, die bei Radiuskorrekturen auf kurzen Verfahrwegen auftreten können. Geben Sie daher für die Fräserdurchmesserkompensation in der Werkzeugtabelle der Steuerung einen Wert nahe null an.",
    "info.correctThreadDiameter.title": "Korrekter Gewindedurchmesser",
    "info.correctThreadDiameter.body": "Bei SmiCut-Gewindefräsern wird der Flankendurchmesser optisch gemessen und der theoretische Außendurchmesser auf jedem Werkzeug lasermarkiert. Geben Sie dieses Maß als Fräserdurchmesser in SmiProg ein, um möglichst schon beim ersten Schnitt den richtigen Gewindedurchmesser zu erzielen. Weitere Korrekturen können Sie in SmiProg oder über die Werkzeugkorrektur der Steuerung vornehmen.",
    "info.customTools.title": "Spezialwerkzeuge",
    "info.customTools.body": "Wenn Ihr Werkzeug nicht in der Liste aufgeführt ist, wählen Sie benutzerdefinierte Werkzeugabmessungen und geben Sie Fräserdurchmesser, Schneidenlänge und Anzahl der Schneiden ein. Prüfen Sie das erzeugte Programm bei der Verwendung von Spezialwerkzeugen sorgfältig.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Geben Sie die gesamte Schneidenlänge des gewählten SmiCut-Vollhartmetall-Gewindefräsers als Gewindelänge ein. Mit ThreadBurr wird das Gewinde in einem Arbeitsgang gefräst und entgratet.",
    "info.threadBurr.link": "ThreadBurr – Gewindefräser aus Hartmetall von SmiCut",
    "info.oneTwoRows.title": "Werkzeuge mit einem Zahn / zwei Zähnen (axial)",
    "info.oneTwoRows.body": "Wenn Sie einen SmiCut-Standardfräser vom Typ NM mit einem oder zwei Zähnen in axialer Richtung wählen, erzeugt SmiProg automatisch eine Spirale, bis das Gewinde fertig ist. Für diesen Zyklus mit einem anderen geeigneten Werkzeug geben Sie bei den benutzerdefinierten Werkzeugabmessungen die Steigung als Schneidenlänge ein. Prüfen Sie vor der Bearbeitung die Eignung des Werkzeugs und das erzeugte Programm.",
    "info.flankInfeed.title": "Flankenzustellung",
    "info.flankInfeed.body": "SmiProg verwendet bei mehreren radialen Durchgängen eine Flankenzustellung. Sie verringert Vibrationen und verbessert die Bearbeitungsstabilität.",
    "info.flankInfeed.link": "Vibrationsfreies Gewindefräsen: Verbesserung von Produktivität und Wirtschaftlichkeit",
    "info.shortCuttingLength.title": "Gewindefräser mit Freistellung",
    "info.shortCuttingLength.body": "Wenn die Schneidenlänge des Werkzeugs kürzer als die gewünschte Gewindelänge ist, teilt SmiProg die Bearbeitung in mehrere axiale Durchgänge auf, sofern der Werkzeugtyp dies unterstützt.",
    "info.inserts.title": "Gewindefräser mit Wendeschneidplatten",
    "info.inserts.body": "Wählen Sie benutzerdefinierte Werkzeugabmessungen und geben Sie den Schneidendurchmesser des Fräserkörpers, die Schneidenlänge der Wendeschneidplatte und die Anzahl der Wendeschneidplatten ein. Bei Bedarf erzeugt SmiProg die gesamte Gewindelänge in mehreren axialen Durchgängen. Prüfen Sie das erzeugte Programm vor der Bearbeitung.",
    "info.taperedThreads.title": "Konische Gewinde",
    "info.taperedThreads.body": "Bei kegeligem Gewinde bezieht sich der Fräserdurchmesser auf den letzten vollständigen Gewindegang nahe dem Schaft. Geben Sie den Gewindedurchmesser an dieser Position ein, um ein korrektes CNC-Programm zu erhalten.",
    "info.warning.title": "Warnung",
    "info.warning.body": "Die in SmiProg angegebenen Schnittdaten sind empfohlene Startwerte. Viele Faktoren können Anpassungen erforderlich machen, darunter Werkstoff, Maschinenstabilität, Spannmittel, Werkzeugaufnahme, Kühlschmierstoff und Späneabfuhr. SmiCut übernimmt keine Haftung für Schäden, die durch die Verwendung des von der Software empfohlenen CNC-Programms oder der Schnittdaten entstehen.",
