    "info.step1.body": "Seleccione el material, el perfil, el tamaño y la longitud de la rosca. Introduzca la distancia de seguridad en Programa CNC. En las roscas M, el paso se indica en milímetros; los demás perfiles utilizan hilos por pulgada (TPI).",
    "info.step2.title": "Seleccione la fresa de roscar",
    "info.step2.body": "Utilice una herramienta SmiCut sugerida o introduzca dimensiones de herramienta personalizadas en la selección de herramientas.",
    "info.step3.title": "Comprobar los resultados",
    "info.step3.body": "Seleccione el proceso de manufactura, el sistema de control y el sentido de la rosca en el programa CNC. Revise los datos de corte, el tiempo de mecanizado y el programa CNC antes del mecanizado.",
    "info.beforeMachining.title": "Antes del mecanizado",
    "info.beforeMachining.body": "Compruebe que la fresa de roscar seleccionada sea adecuada para el diámetro, el paso y la longitud de la rosca. Verifique el programa mediante simulación o ejecución bloque a bloque antes de iniciar la producción.",
    "info.figureAlt": "Esquema de fresado de roscas con diámetro de rosca, paso, longitud de rosca, longitud de corte, distancia de seguridad y diámetro de la fresa.",
    "info.figure.threadDiameter": "Diámetro de la rosca",
    "info.figure.pitch": "Paso",
    "info.figure.threadLength": "Longitud de rosca",
    "info.figure.safetyDistance": "Distancia de seguridad",
    "info.figure.cutterDiameter": "Diámetro de la fresa",
    "info.figure.cuttingLength": "Longitud de corte",
    "info.machiningNotes": "Notas de mecanizado",
    "info.toolCompensation.title": "Compensación de la herramienta",
    "info.toolCompensation.body": "En SmiProg, la compensación de la herramienta se utiliza solo para ajustes menores. Esto reduce los problemas que pueden surgir al compensar el radio en movimientos cortos. Utilice un valor cercano a cero para la compensación del diámetro de la fresa en la tabla de herramientas del control numérico.",
    "info.correctThreadDiameter.title": "Diámetro de rosca correcto",
    "info.correctThreadDiameter.body": "El diámetro medio de las fresas de roscar de SmiCut se mide ópticamente y el diámetro exterior teórico se marca con láser en cada herramienta. Introduzca esta medida como diámetro de la fresa en SmiProg para obtener el diámetro de rosca correcto desde la primera pasada. Si necesita más ajustes, puede modificar el valor en SmiProg o la compensación de la herramienta en el control numérico.",
    "info.customTools.title": "Herramientas especiales",
    "info.customTools.body": "Si su herramienta no está en la lista, seleccione dimensiones de herramienta personalizadas e introduzca el diámetro de la fresa, la longitud de corte y el número de labios. Compruebe cuidadosamente el programa generado al utilizar herramientas especiales.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Introduzca la longitud de corte completa de la fresa de roscar de metal duro integral SmiCut en el campo de longitud de rosca. Así, ThreadBurr fresa y desbarba la rosca en la misma operación.",
    "info.threadBurr.link": "ThreadBurr – Fresas de Roscar de Carburo Sólido",
    "info.oneTwoRows.title": "Herramientas con uno o dos dientes (axial)",
    "info.oneTwoRows.body": "Al seleccionar una fresa estándar SmiCut de tipo NM con uno o dos dientes en sentido axial, SmiProg genera automáticamente una espiral hasta completar la rosca. Para usar este ciclo con otra herramienta adecuada, introduzca el paso como longitud de corte en las dimensiones de herramienta personalizadas. Compruebe la idoneidad de la herramienta y el programa generado antes del mecanizado.",
    "info.flankInfeed.title": "Penetración por el flanco",
    "info.flankInfeed.body": "SmiProg utiliza la penetración por el flanco al programar varias pasadas radiales. Esto reduce las vibraciones y mejora la estabilidad del mecanizado.",
    "info.flankInfeed.link": "Fresado de Roscas Sin Vibraciones: Mejorando la Productividad y la Economía",
    "info.shortCuttingLength.title": "Fresas de roscar con cuello reducido",
    "info.shortCuttingLength.body": "Si la herramienta seleccionada tiene una longitud de corte más corta que la longitud de rosca solicitada, SmiProg divide la operación en varias pasadas axiales cuando el tipo de herramienta lo permite.",
    "info.inserts.title": "Herramientas con plaquitas",
    "info.inserts.body": "Seleccione dimensiones de herramienta personalizadas e introduzca el diámetro de corte del cuerpo de la fresa, la longitud de corte de la plaquita y el número de plaquitas. Si es necesario, SmiProg completa toda la longitud de la rosca en varias pasadas axiales. Compruebe el programa generado antes del mecanizado.",
    "info.taperedThreads.title": "Roscas cónicas",
    "info.taperedThreads.body": "En las roscas cónicas, el diámetro de la fresa corresponde al último filete completo más próximo al mango. Introduzca el diámetro de rosca en esa posición para obtener un programa CNC correcto.",
    "info.warning.title": "Advertencia",
    "info.warning.body": "Los datos de corte en SmiProg son datos iniciales recomendados. Muchos factores pueden requerir ajustes, incluyendo el material de la pieza, la estabilidad de la máquina, la fijación, la configuración de la herramienta, el refrigerante y la evacuación de virutas. SmiCut no se hace responsable de los daños causados por el uso del programa CNC o de los datos de corte recomendados por el software.",
    "materialSelector.welcomeTitle": "¿Qué material va a mecanizar?",
