    "compare.result": "Résultat",
    "tool.enterThreadLength": "Longueur de filetage",
    "tool.noMatchingTool": "Aucun outil correspondant n'a été trouvé pour le filetage et la longueur de filetage sélectionnés.",
    "tool.customDimensions": "➜ Dimensions d'outil personnalisées",
    "tool.custom": "Outil personnalisé",
    "tool.linkText": "➜ Voir la page de l'outil pour toutes les dimensions et le fichier 3D STEP",
    "info.howToUse": "Comment utiliser SmiProg",
    "info.step1.title": "Définir le filetage",
    "info.step1.body": "Sélectionnez le matériau, le profil, la dimension et la longueur du filetage. Saisissez la distance de sécurité dans Programme CNC. Pour les filetages M, le pas est exprimé en millimètres ; les autres profils utilisent le nombre de filets par pouce (TPI).",
    "info.step2.title": "Sélectionner la fraise à fileter",
    "info.step2.body": "Utilisez un outil SmiCut suggéré ou entrez des dimensions d'outil personnalisées dans la sélection d'outil.",
    "info.step3.title": "Vérifier les résultats",
    "info.step3.body": "Sélectionnez le mode d’usinage, la commande numérique et le sens du filetage dans Programme CNC. Vérifiez les données de coupe, le temps d’usinage et le programme CNC avant l’usinage.",
    "info.beforeMachining.title": "Avant l'usinage",
    "info.beforeMachining.body": "Vérifiez que la fraise à fileter sélectionnée convient au diamètre, au pas et à la longueur du filetage. Contrôlez le programme par simulation ou en mode bloc par bloc avant de lancer la production.",
    "info.figureAlt": "Schéma de fraisage de filetage indiquant le diamètre du filetage, le pas, la longueur du filetage, la longueur de coupe, la distance de sécurité et le diamètre de la fraise.",
    "info.figure.threadDiameter": "Diamètre du filetage",
    "info.figure.pitch": "Pas",
    "info.figure.threadLength": "Longueur de filetage",
    "info.figure.safetyDistance": "Distance de sécurité",
    "info.figure.cutterDiameter": "Diamètre de la fraise",
    "info.figure.cuttingLength": "Longueur de coupe",
    "info.machiningNotes": "Notes d'usinage",
    "info.toolCompensation.title": "Correction d’outil",
    "info.toolCompensation.body": "Dans SmiProg, la correction d’outil sert uniquement aux petits ajustements. Cela réduit les problèmes liés à la correction de rayon lors de déplacements courts. Utilisez donc une valeur proche de zéro pour la correction du diamètre de fraise dans la table d’outils de la commande numérique.",
    "info.correctThreadDiameter.title": "Diamètre de filetage correct",
    "info.correctThreadDiameter.body": "Le diamètre sur flancs des fraises à fileter SmiCut est mesuré par voie optique et le diamètre extérieur théorique est gravé au laser sur chaque fraise. Saisissez cette valeur comme diamètre de fraise dans SmiProg pour obtenir le bon diamètre de filetage dès la première passe. Si un ajustement est nécessaire, modifiez la valeur dans SmiProg ou la correction d’outil dans la commande numérique.",
    "info.customTools.title": "Outils non répertoriés ou spéciaux",
    "info.customTools.body": "Si votre outil ne figure pas dans la liste, choisissez les dimensions d’outil personnalisées et saisissez le diamètre de la fraise, la longueur de coupe et le nombre de dents. Vérifiez attentivement le programme généré lorsque vous utilisez des outils non répertoriés ou spéciaux.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Saisissez la longueur de coupe totale de la fraise à fileter SmiCut en carbure monobloc dans le champ de longueur du filetage. ThreadBurr permet ainsi de fraiser et d’ébavurer le filetage en une seule opération.",
    "info.threadBurr.link": "ThreadBurr : les fraises à fileter en carbure monobloc de SmiCut",
    "info.oneTwoRows.title": "Fraises à fileter avec une ou deux dents par goujure",
    "info.oneTwoRows.body": "Lorsque vous choisissez une fraise standard SmiCut de type NM avec une ou deux dents par goujure, SmiProg génère automatiquement une spirale jusqu’à la fin du filetage. Pour utiliser ce cycle avec un autre outil adapté, saisissez le pas comme longueur de coupe dans les dimensions d’outil personnalisées. Vérifiez que l’outil convient et contrôlez le programme généré avant l’usinage.",
    "info.flankInfeed.title": "Pénétration par le flanc",
    "info.flankInfeed.body": "SmiProg utilise une pénétration par le flanc lors de la programmation de plusieurs passes radiales. Cette méthode réduit les vibrations et améliore la stabilité de l’usinage.",
    "info.flankInfeed.link": "Fraisage de filetage anti-vibration : Améliorer la productivité et la rentabilité",
    "info.shortCuttingLength.title": "Fraises à fileter à col réduit",
    "info.shortCuttingLength.body": "Si l'outil sélectionné a une longueur de coupe plus courte que la longueur de filetage demandée, SmiProg divise l'opération en plusieurs passes axiales lorsque le type d'outil le permet.",
    "info.inserts.title": "Fraises à fileter à plaquettes indexables",
    "info.inserts.body": "Choisissez les dimensions d’outil personnalisées et saisissez le diamètre de coupe du corps de fraise, la longueur de coupe de la plaquette et le nombre de plaquettes. Si nécessaire, SmiProg réalise toute la longueur du filetage en plusieurs passes axiales. Vérifiez le programme généré avant l’usinage.",
    "info.taperedThreads.title": "Filetages coniques",
    "info.taperedThreads.body": "Pour les filetages coniques, le diamètre de la fraise correspond au dernier filet complet le plus proche de la queue. Saisissez le diamètre du filetage à cet endroit pour obtenir un programme CNC correct.",
    "info.warning.title": "Avertissement",
    "info.warning.body": "Les données de coupe dans SmiProg sont des données de départ recommandées. De nombreux facteurs peuvent nécessiter des ajustements, notamment la matière de la pièce, la stabilité de la machine, le serrage, le montage de l'outil, le fluide de refroidissement et l'évacuation des copeaux. SmiCut décline toute responsabilité en cas de dommages causés par l'utilisation du programme CNC ou des données de coupe recommandées par le logiciel.",
    "materialSelector.welcomeTitle": "Quel matériau allez-vous usiner ?",
