    "tool.custom": "Alat khusus",
    "tool.linkText": "➜ Lihat halaman alat untuk semua dimensi dan file 3D STEP",
    "info.howToUse": "Cara menggunakan SmiProg",
    "info.step1.title": "Tentukan ulir",
    "info.step1.body": "Pilih material, profil, ukuran, dan panjang ulir. Masukkan jarak aman pada Program CNC. Untuk ulir M, pitch dinyatakan dalam milimeter; profil lain menggunakan jumlah ulir per inci (TPI).",
    "info.step2.title": "Pilih thread mill",
    "info.step2.body": "Gunakan tool SmiCut yang disarankan atau masukkan dimensi tool kustom pada pemilihan tool.",
    "info.step3.title": "Periksa output",
    "info.step3.body": "Pilih proses manufaktur, sistem kontrol, dan arah ulir pada Program CNC. Periksa data pemotongan, waktu pemesinan, dan program CNC sebelum pemesinan.",
    "info.beforeMachining.title": "Sebelum pemesinan",
    "info.beforeMachining.body": "Pastikan thread mill yang dipilih sesuai untuk diameter, pitch, dan panjang ulir yang akan dikerjakan. Periksa program melalui simulasi atau mode blok tunggal sebelum produksi.",
    "info.figureAlt": "Gambar dimensi frais ulir yang menunjukkan diameter ulir, pitch, panjang ulir, panjang potong, jarak aman, dan diameter cutter.",
    "info.figure.threadDiameter": "Diameter ulir",
    "info.figure.pitch": "Pitch",
    "info.figure.threadLength": "Panjang ulir",
    "info.figure.safetyDistance": "Jarak aman",
    "info.figure.cutterDiameter": "Diameter cutter",
    "info.figure.cuttingLength": "Panjang potong",
    "info.machiningNotes": "Catatan Pemesinan",
    "info.toolCompensation.title": "Kompensasi Tool",
    "info.toolCompensation.body": "SmiProg menggunakan kompensasi tool hanya untuk penyesuaian kecil. Hal ini mengurangi masalah akibat kompensasi radius pada gerakan pendek. Gunakan nilai mendekati nol untuk kompensasi diameter cutter pada tabel tool sistem kontrol.",
    "info.correctThreadDiameter.title": "Diameter Ulir yang Benar",
    "info.correctThreadDiameter.body": "Diameter pitch thread mill SmiCut diukur secara optik, lalu diameter luar teoretis ditandai dengan laser pada setiap tool. Masukkan nilai ini sebagai diameter cutter di SmiProg untuk membantu mendapatkan diameter ulir yang tepat sejak pemotongan pertama. Jika perlu penyesuaian lebih lanjut, ubah nilainya di SmiProg atau kompensasi tool pada sistem kontrol.",
    "info.customTools.title": "Tool di Luar Daftar dan Tool Khusus",
    "info.customTools.body": "Jika tool tidak ada dalam daftar, pilih dimensi tool kustom dan masukkan diameter cutter, panjang potong, serta jumlah mata potong. Periksa program yang dihasilkan dengan cermat saat menggunakan tool khusus.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Masukkan seluruh panjang potong thread mill karbida solid SmiCut pada kolom panjang ulir. Dengan ThreadBurr, pengefraisan ulir dan penghilangan burr dilakukan dalam satu operasi.",
    "info.threadBurr.link": "ThreadBurr – Solid Carbide Thread Mills dari SmiCut",
    "info.oneTwoRows.title": "Thread Mill dengan Satu atau Dua Gigi per Alur",
    "info.oneTwoRows.body": "Saat thread mill SmiCut standar tipe NM dengan satu atau dua gigi per alur dipilih, SmiProg otomatis membuat lintasan spiral hingga ulir selesai. Untuk menggunakan siklus ini dengan tool lain yang sesuai, masukkan pitch sebagai panjang potong pada dimensi tool kustom. Periksa kesesuaian tool dan program yang dihasilkan sebelum pemesinan.",
    "info.flankInfeed.title": "Flank Infeed",
    "info.flankInfeed.body": "SmiProg menggunakan flank infeed saat memprogram beberapa pass radial. Ini membantu mengurangi getaran dan meningkatkan stabilitas pemesinan.",
    "info.flankInfeed.link": "Vibration-Free Thread Milling: Improving Productivity and Economy",
    "info.shortCuttingLength.title": "Thread Mill dengan Leher yang Diperkecil",
    "info.shortCuttingLength.body": "Jika panjang potong tool lebih pendek dari panjang ulir yang diperlukan, SmiProg membagi pemesinan menjadi beberapa lintasan aksial apabila jenis tool mendukungnya.",
    "info.inserts.title": "Thread Mills dengan Insert",
    "info.inserts.body": "Pilih dimensi tool kustom dan masukkan diameter potong badan cutter, panjang mata potong insert, serta jumlah insert. Jika diperlukan, SmiProg mengerjakan seluruh panjang ulir dalam beberapa lintasan aksial. Periksa program yang dihasilkan sebelum pemesinan.",
    "info.taperedThreads.title": "Ulir tirus",
    "info.taperedThreads.body": "Untuk ulir tirus, diameter pemotong mengacu pada ulir penuh terakhir yang paling dekat dengan tangkai. Masukkan diameter ulir pada posisi tersebut untuk menghasilkan program CNC yang benar.",
    "info.warning.title": "Peringatan",
