    "info.howToUse": "Come usare SmiProg",
    "info.step1.title": "Definire la filettatura",
    "info.step1.body": "Selezionare il materiale, il profilo, la dimensione e la lunghezza della filettatura. Inserire la distanza di sicurezza in Programma CNC. Per le filettature M, il passo si indica in millimetri; gli altri profili utilizzano filetti per pollice (TPI).",
    "info.step2.title": "Selezionare la fresa a filettare",
    "info.step2.body": "Utilizzare un utensile SmiCut suggerito o inserire le dimensioni personalizzate dell'utensile nella selezione dell'utensile.",
    "info.step3.title": "Verificare i risultati",
    "info.step3.body": "Selezionare il processo di produzione, il sistema di controllo e il senso della filettatura nel programma CNC. Rivedere i dati di taglio, il tempo di lavorazione e il programma CNC prima della lavorazione.",
    "info.beforeMachining.title": "Prima della lavorazione",
    "info.beforeMachining.body": "Verificare che la fresa a filettare selezionata sia adatta al diametro, al passo e alla lunghezza del filetto. Controllare il programma mediante simulazione o esecuzione in blocco singolo prima di avviare la produzione.",
    "info.figureAlt": "Schema della fresatura di filetti con diametro della filettatura, passo, lunghezza del filetto, lunghezza tagliente, distanza di sicurezza e diametro della fresa.",
    "info.figure.threadDiameter": "Diametro filettatura",
    "info.figure.pitch": "Passo",
    "info.figure.threadLength": "Lunghezza del filetto",
    "info.figure.safetyDistance": "Distanza di sicurezza",
    "info.figure.cutterDiameter": "Diametro fresa",
    "info.figure.cuttingLength": "Lunghezza di taglio",
    "info.machiningNotes": "Note di lavorazione",
    "info.toolCompensation.title": "Compensazione utensile",
    "info.toolCompensation.body": "In SmiProg, la compensazione utensile viene usata solo per piccole correzioni. Questo riduce i problemi che possono verificarsi con la compensazione del raggio nei movimenti brevi. Utilizzare quindi un valore vicino allo zero per la compensazione del diametro della fresa nella tabella utensili del controllo numerico.",
    "info.correctThreadDiameter.title": "Diametro corretto della filettatura",
    "info.correctThreadDiameter.body": "Il diametro medio delle frese a filettare SmiCut viene misurato otticamente e il diametro esterno teorico viene marcato a laser su ogni utensile. Inserisci questa misura come diametro della fresa in SmiProg per ottenere il diametro corretto del filetto fin dalla prima lavorazione. Se sono necessarie ulteriori correzioni, modifica il valore in SmiProg o la compensazione utensile nel controllo numerico.",
    "info.customTools.title": "Utensili non in lista o speciali",
    "info.customTools.body": "Se l’utensile non è in lista, selezionare le dimensioni personalizzate dell’utensile e inserire il diametro della fresa, la lunghezza tagliente e il numero dei taglienti. Verificare attentamente il programma generato quando si utilizzano utensili speciali.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Inserire l’intera lunghezza di taglio della fresa a filettare SmiCut in metallo duro integrale nel campo della lunghezza del filetto. ThreadBurr esegue la fresatura e la sbavatura del filetto in un’unica operazione.",
    "info.threadBurr.link": "ThreadBurr – frese a filettare in metallo duro",
    "info.oneTwoRows.title": "Frese a filettare con uno o due denti (assiali)",
    "info.oneTwoRows.body": "Selezionando una fresa standard SmiCut di tipo NM con uno o due denti in senso assiale, SmiProg genera automaticamente una spirale fino al completamento del filetto. Per usare questo ciclo con un altro utensile adatto, inserire il passo come lunghezza tagliente nelle dimensioni personalizzate dell’utensile. Verificare l’idoneità dell’utensile e il programma generato prima della lavorazione.",
    "info.flankInfeed.title": "Penetrazione sul fianco",
    "info.flankInfeed.body": "SmiProg utilizza la penetrazione sul fianco quando si programmano più passate radiali. Questo riduce le vibrazioni e migliora la stabilità della lavorazione.",
    "info.flankInfeed.link": "Fresatura dei filetti senza vibrazioni: migliore produttività e ottimizzazione dei costi",
    "info.shortCuttingLength.title": "Frese a filettare con collo scaricato",
    "info.shortCuttingLength.body": "Se la lunghezza tagliente dell’utensile è inferiore alla lunghezza del filetto richiesta, SmiProg suddivide la lavorazione in più passate assiali, quando il tipo di utensile lo consente.",
    "info.inserts.title": "Frese a filettare ad inserti intercambiabili",
    "info.inserts.body": "Selezionare le dimensioni personalizzate dell’utensile e inserire il diametro di taglio del corpo fresa, la lunghezza tagliente dell’inserto e il numero di inserti. Se necessario, SmiProg esegue l’intera lunghezza del filetto in più passate assiali. Verificare il programma generato prima della lavorazione.",
    "info.taperedThreads.title": "Filettature coniche",
    "info.taperedThreads.body": "Per i filetti conici, il diametro della fresa si riferisce all’ultimo filetto completo più vicino al codolo. Inserisci il diametro del filetto in quella posizione per ottenere un programma CNC corretto.",
    "info.warning.title": "Avviso",
    "info.warning.body": "I dati di taglio in SmiProg sono dati di avvio consigliati. Molti fattori possono richiedere regolazioni, tra cui il materiale del pezzo, la stabilità della macchina, il fissaggio, la configurazione dell'utensile, il refrigerante e l'evacuazione dei trucioli. SmiCut non si assume la responsabilità per danni causati dall'utilizzo del programma CNC o dei dati di taglio consigliati dal software.",
