    "info.step1.title": "나사 정의",
    "info.step1.body": "소재, 나사 형상, 크기 및 나사 길이를 선택하십시오. 안전 거리는 CNC 프로그램 항목에서 입력하십시오. M 나사의 피치는 밀리미터로 지정하고 다른 형상은 인치당 나사산 수(TPI)를 사용합니다.",
