    "info.step3.title": "출력 확인",
    "info.step3.body": "CNC 프로그램에서 제조 공정, 제어 시스템 및 나사 방향을 선택하십시오. 가공 전에 절삭 데이터, 가공 시간 및 CNC 프로그램을 확인하십시오.",
    "info.beforeMachining.title": "가공 전",
    "info.beforeMachining.body": "선택한 쓰레드 밀이 지정된 나사 직경, 피치 및 나사 길이에 적합한지 확인하십시오. 생산 전에 시뮬레이션 또는 싱글 블록 운전으로 프로그램을 확인하십시오.",
    "info.figureAlt": "나사 직경, 피치, 나사 길이, 절삭날 길이, 안전 거리 및 공구 직경을 보여 주는 나사 밀링 치수도.",
    "info.figure.threadDiameter": "나사 직경",
    "info.figure.pitch": "피치",
    "info.figure.threadLength": "나사 길이",
    "info.figure.safetyDistance": "안전 거리",
    "info.figure.cutterDiameter": "커터 직경",
    "info.figure.cuttingLength": "날 길이",
    "info.machiningNotes": "가공 참고 사항",
    "info.toolCompensation.title": "공구 보정",
    "info.toolCompensation.body": "SmiProg에서는 공구 보정을 미세 조정에만 사용합니다. 이는 짧은 이동에서 반경 보정을 사용할 때 발생하는 문제를 줄여 줍니다. 따라서 제어 시스템의 공구 테이블에서 공구 직경 보정값을 0에 가까운 값으로 설정하십시오.",
    "info.correctThreadDiameter.title": "정확한 나사 직경",
    "info.correctThreadDiameter.body": "SmiCut 나사 밀링 공구의 유효 직경은 광학적으로 측정되며, 이론적 외경은 각 공구에 레이저로 표시됩니다. 첫 가공부터 올바른 나사 직경을 얻을 수 있도록 이 값을 SmiProg의 공구 직경으로 입력하세요. 추가 조정이 필요하면 SmiProg의 입력값이나 제어 시스템의 공구 보정값을 조정하세요.",
    "info.customTools.title": "목록에 없는 공구 및 특수 공구",
    "info.customTools.body": "공구가 목록에 없으면 공구 선택에서 사용자 지정 공구 치수를 선택하고 공구 직경, 절삭날 길이 및 절삭날 수를 입력하십시오. 특수 공구를 사용할 때는 생성된 프로그램을 주의 깊게 확인하십시오.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "나사 길이 칸에 선택한 SmiCut 초경 솔리드 스레드 밀의 전체 날 길이를 입력하십시오. ThreadBurr로 나사 가공과 버 제거를 한 공정에서 수행할 수 있습니다.",
    "info.threadBurr.link": "SmiCut 솔리드 타입 초경 쓰레드밀 – ThreadBurr",
    "info.oneTwoRows.title": "절삭날당 하나 또는 두 개의 나사산을 가진 쓰레드 밀",
    "info.oneTwoRows.body": "절삭날당 축 방향으로 하나 또는 두 개의 나사산을 가진 SmiCut 표준 NM 타입을 선택하면 SmiProg가 나사가 완성될 때까지 나선 경로를 자동으로 생성합니다. 다른 적합한 공구로 같은 사이클을 사용하려면 사용자 지정 공구 치수에서 피치를 절삭날 길이로 입력하십시오. 가공 전에 공구의 적합성과 생성된 프로그램을 확인하십시오.",
    "info.flankInfeed.title": "플랭크 인피드",
    "info.flankInfeed.body": "SmiProg는 여러 반경 방향 패스를 프로그램할 때 나사산 측면을 따라 절입하는 플랭크 인피드를 사용합니다. 이는 진동을 줄이고 가공 안정성을 높입니다.",
    "info.flankInfeed.link": "Vibration-Free Thread Milling: Improving Productivity and Economy",
    "info.shortCuttingLength.title": "목이 가는 나사 밀링 공구",
    "info.shortCuttingLength.body": "공구의 절삭날 길이가 필요한 나사 길이보다 짧고 공구 유형이 허용하는 경우, SmiProg는 여러 축 방향 패스로 나사를 가공합니다.",
    "info.inserts.title": "교환용 인서트를 사용하는 쓰레드 밀링 커터",
    "info.inserts.body": "사용자 지정 공구 치수를 선택하고 커터 몸체의 절삭 직경, 인서트의 절삭날 길이 및 인서트 수를 입력하십시오. 필요한 경우 SmiProg가 여러 축 방향 패스로 전체 나사 길이를 가공합니다. 가공 전에 생성된 프로그램을 확인하십시오.",
    "info.taperedThreads.title": "테이퍼 나사",
    "info.taperedThreads.body": "테이퍼 나사의 공구 직경은 생크에 가장 가까운 마지막 완전 나사산을 기준으로 합니다. 올바른 CNC 프로그램을 위해 해당 위치의 나사 직경을 입력하세요.",
    "info.warning.title": "경고",
    "info.warning.body": "SmiProg의 절삭 데이터는 권장 시작 데이터입니다. 작업물 소재, 기계 안정성, 고정구, 공구 설정, 냉각 및 칩 배출 등 여러 요인으로 인해 조정이 필요할 수 있습니다. SmiCut은 이 소프트웨어가 권장하는 CNC 프로그램 또는 절삭 데이터 사용으로 인한 손상에 대해 책임지지 않습니다.",
