    "compare.result": "Resultaat",
    "tool.enterThreadLength": "Schroefdraadlengte",
    "tool.noMatchingTool": "Er is geen passend gereedschap gevonden voor de geselecteerde schroefdraad en schroefdraadlengte.",
    "tool.customDimensions": "➜ Aangepaste gereedschapsafmetingen",
    "tool.custom": "Aangepast gereedschap",
    "tool.linkText": "➜ Zie gereedschapspagina voor alle afmetingen en 3D STEP-bestand",
    "info.howToUse": "Hoe SmiProg te gebruiken",
    "info.step1.title": "Definieer de schroefdraad",
    "info.step1.body": "Selecteer materiaal, schroefdraadprofiel, maat en schroefdraadlengte. Voer de veiligheidsafstand in onder CNC-programma. Bij M-schroefdraad wordt de spoed in millimeters opgegeven; andere profielen gebruiken het aantal gangen per inch (TPI).",
    "info.step2.title": "Selecteer de draadfrees",
    "info.step2.body": "Gebruik een voorgesteld SmiCut-gereedschap of voer aangepaste gereedschapsafmetingen in bij de gereedschapsselectie.",
    "info.step3.title": "Controleer de uitvoer",
    "info.step3.body": "Selecteer de bewerkingsmethode, de besturing en de schroefdraadrichting onder CNC-programma. Controleer de snijgegevens, de bewerkingstijd en het CNC-programma vóór de bewerking.",
    "info.beforeMachining.title": "Voorafgaand aan het bewerken",
    "info.beforeMachining.body": "Controleer of de geselecteerde draadfrees geschikt is voor de schroefdraaddiameter, spoed en schroefdraadlengte. Controleer het programma in een simulatie of in enkelblokmodus voordat u de productie start.",
    "info.figureAlt": "Maatschets voor draadfrezen met schroefdraaddiameter, spoed, schroefdraadlengte, snijlengte, veiligheidsafstand en freesdiameter.",
    "info.figure.threadDiameter": "Schroefdraaddiameter",
    "info.figure.pitch": "Spoed",
    "info.figure.threadLength": "Schroefdraadlengte",
    "info.figure.safetyDistance": "Veiligheidsafstand",
    "info.figure.cutterDiameter": "Freesdiameter",
    "info.figure.cuttingLength": "Snijlengte",
    "info.machiningNotes": "Bewerkingsnotities",
    "info.toolCompensation.title": "Gereedschapscompensatie",
    "info.toolCompensation.body": "In SmiProg wordt gereedschapscompensatie alleen gebruikt voor kleine correcties. Dit vermindert problemen die kunnen ontstaan bij radiuscompensatie tijdens korte bewegingen. Gebruik daarom een waarde dicht bij nul voor de freesdiametercompensatie in de gereedschapstabel van de besturing.",
    "info.correctThreadDiameter.title": "Correcte schroefdraaddiameter",
    "info.correctThreadDiameter.body": "Bij SmiCut-draadfrezen wordt de flankdiameter optisch gemeten en wordt de theoretische buitendiameter op elke frees met een laser gemarkeerd. Voer deze maat in als freesdiameter in SmiProg om vanaf de eerste bewerking de juiste schroefdraaddiameter te bereiken. Verdere correcties kunt u uitvoeren in SmiProg of via de gereedschapscompensatie in de besturing.",
    "info.customTools.title": "Speciaalgereedschap",
    "info.customTools.body": "Als uw gereedschap niet in de lijst staat, kies dan aangepaste gereedschapsafmetingen en voer de freesdiameter, snijlengte en het aantal snijkanten in. Controleer het gegenereerde programma zorgvuldig bij gebruik van speciaalgereedschap.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "Vul de volledige snijlengte van de gekozen volhardmetalen draadfrees van SmiCut in bij de draadlengte. Met ThreadBurr worden draadfrezen en ontbramen zo in één bewerking uitgevoerd.",
    "info.threadBurr.link": "ThreadBurr – volhardmetalen draadfrezen van SmiCut",
    "info.oneTwoRows.title": "Draadfrezen met een tand / twee tanden (axiaal)",
    "info.oneTwoRows.body": "Als u een standaard SmiCut-frees van het type NM met één of twee tanden in axiale richting kiest, genereert SmiProg automatisch een spiraal tot de schroefdraad klaar is. Voor deze cyclus met een ander geschikt gereedschap voert u de spoed in als snijlengte bij de aangepaste gereedschapsafmetingen. Controleer vóór de bewerking of het gereedschap geschikt is en controleer het gegenereerde programma.",
    "info.flankInfeed.title": "Flanktoevoer",
    "info.flankInfeed.body": "SmiProg gebruikt flanktoevoer bij het programmeren van meerdere radiale gangen. Dit vermindert trillingen en verbetert de bewerkingsstabiliteit.",
    "info.flankInfeed.link": "Vibratievrij draadfrezen voor hogere productiviteit",
    "info.shortCuttingLength.title": "Draadfrezen met gereduceerde hals",
    "info.shortCuttingLength.body": "Als de snijlengte van het gereedschap korter is dan de gewenste schroefdraadlengte, verdeelt SmiProg de bewerking over meerdere axiale gangen, mits het gereedschapstype dit ondersteunt.",
    "info.inserts.title": "Draadfrezen met wisselplaten",
    "info.inserts.body": "Kies aangepaste gereedschapsafmetingen en voer de snijdiameter van de freesbody, de snijlengte van de wisselplaat en het aantal wisselplaten in. Indien nodig maakt SmiProg de volledige schroefdraadlengte in meerdere axiale gangen. Controleer het gegenereerde programma vóór de bewerking.",
    "info.taperedThreads.title": "Conische schroefdraad",
    "info.taperedThreads.body": "Bij conische schroefdraad heeft de freesdiameter betrekking op de laatste volledige draadgang het dichtst bij de schacht. Voer de draaddiameter op die positie in voor een correct CNC-programma.",
    "info.warning.title": "Waarschuwing",
    "info.warning.body": "De snijgegevens in SmiProg zijn aanbevolen startwaarden. Veel factoren kunnen aanpassingen vereisen, waaronder werkstukmateriaal, machine-stabiliteit, spanmiddelen, gereedschapsopstelling, koelmiddel en spaanafvoer. SmiCut aanvaardt geen aansprakelijkheid voor schade veroorzaakt door het gebruik van het CNC-programma of de door de software aanbevolen snijgegevens.",
    "materialSelector.welcomeTitle": "Welk materiaal gaat u bewerken?",
