    "compare.password": "Hasło",
    "compare.lockHelp": "Wprowadź własne ceny narzędzi. Dystrybutorzy SmiCut mogą poprosić firmę SmiCut o hasło umożliwiające wyświetlenie cen katalogowych.",
    "compare.enterThreadLength": "Wprowadź długość gwintu, aby porównać narzędzia.",
    "compare.result": "Wynik",
    "tool.enterThreadLength": "Długość gwintu",
    "tool.noMatchingTool": "Nie znaleziono pasującego narzędzia dla wybranego gwintu i długości gwintu.",
