    "tool.custom": "Narzędzie niestandardowe",
    "tool.linkText": "➜ Zobacz stronę narzędzia, aby uzyskać wszystkie wymiary i plik 3D STEP",
    "info.howToUse": "Jak korzystać z SmiProg",
    "info.step1.title": "Zdefiniuj gwint",
    "info.step1.body": "Wybierz materiał, zarys, rozmiar i długość gwintu. Odstęp bezpieczeństwa wprowadź w sekcji Program CNC. Dla gwintów M skok podaje się w milimetrach; dla pozostałych zarysów używa się liczby zwojów na cal (TPI).",
    "info.step2.title": "Wybierz frez gwintowy",
    "info.step2.body": "Użyj sugerowanego frezu SmiCut lub wpisz niestandardowe wymiary narzędzia w selekcji narzędzi.",
    "info.step3.title": "Sprawdź wynik",
    "info.step3.body": "W sekcji programu CNC wybierz proces produkcji, układ sterowania i kierunek gwintu. Przed obróbką sprawdź dane skrawania, czas obróbki i program CNC.",
    "info.beforeMachining.title": "Przed obróbką",
    "info.beforeMachining.body": "Sprawdź, czy wybrany frez do gwintów jest odpowiedni do średnicy, skoku i długości gwintu. Przed rozpoczęciem produkcji sprawdź program w symulacji lub w trybie pojedynczych bloków.",
    "info.figureAlt": "Szkic wymiarowy frezowania gwintu przedstawiający średnicę gwintu, skok, długość gwintu, długość części skrawającej, odstęp bezpieczeństwa i średnicę freza.",
    "info.figure.threadDiameter": "Średnica gwintu",
    "info.figure.pitch": "Skok",
    "info.figure.threadLength": "Długość gwintu",
    "info.figure.safetyDistance": "Odstęp bezpieczeństwa",
    "info.figure.cutterDiameter": "Średnica frezu",
    "info.figure.cuttingLength": "Długość części skrawającej",
    "info.machiningNotes": "Uwagi dotyczące obróbki",
    "info.toolCompensation.title": "Kompensacja narzędzia",
    "info.toolCompensation.body": "W SmiProg kompensacja narzędzia służy tylko do drobnych korekt. Ogranicza to problemy związane z kompensacją promienia podczas krótkich przemieszczeń. Dlatego w tabeli narzędzi sterowania CNC należy ustawić wartość kompensacji średnicy freza bliską zeru.",
    "info.correctThreadDiameter.title": "Poprawna średnica gwintu",
    "info.correctThreadDiameter.body": "Średnica podziałowa frezów do gwintów SmiCut jest mierzona optycznie, a teoretyczna średnica zewnętrzna jest oznaczana laserowo na każdym narzędziu. Wprowadź tę wartość jako średnicę freza w SmiProg, aby uzyskać prawidłową średnicę gwintu już przy pierwszej obróbce. W razie potrzeby skoryguj wartość w SmiProg lub kompensację narzędzia w sterowaniu CNC.",
    "info.customTools.title": "Narzędzia spoza listy i specjalne",
    "info.customTools.body": "Jeśli narzędzia nie ma na liście, wybierz niestandardowe wymiary narzędzia i wprowadź średnicę freza, długość części skrawającej oraz liczbę ostrzy. Przy użyciu narzędzi specjalnych dokładnie sprawdź wygenerowany program.",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "W polu długości gwintu podaj pełną długość części skrawającej wybranego pełnowęglikowego frezu SmiCut. Dzięki ThreadBurr frezowanie gwintu i usuwanie zadziorów odbywa się w jednej operacji.",
    "info.threadBurr.link": "ThreadBurr – pełnowęglikowe frezy do gwintów firmy SmiCut",
    "info.oneTwoRows.title": "Frezy do gwintów z jednym lub dwoma zębami na ostrzu",
    "info.oneTwoRows.body": "Po wybraniu standardowego freza SmiCut typu NM z jednym lub dwoma zębami na ostrzu SmiProg automatycznie tworzy tor spiralny aż do ukończenia gwintu. Aby użyć tego cyklu z innym odpowiednim narzędziem, wprowadź skok jako długość części skrawającej w niestandardowych wymiarach narzędzia. Przed obróbką sprawdź przydatność narzędzia i wygenerowany program.",
    "info.flankInfeed.title": "Dosuw wzdłuż boku zarysu",
    "info.flankInfeed.body": "Podczas programowania kilku przejść promieniowych SmiProg stosuje dosuw wzdłuż boku zarysu gwintu. Ogranicza to drgania i poprawia stabilność obróbki.",
    "info.flankInfeed.link": "Bezdrganiowe frezowanie gwintów: lepsza produktywność i ekonomiczność",
    "info.shortCuttingLength.title": "Frezy do gwintów z przewężoną szyjką",
    "info.shortCuttingLength.body": "Jeśli długość części skrawającej wybranego narzędzia jest mniejsza od wymaganej długości gwintu, SmiProg dzieli obróbkę na kilka przejść osiowych, o ile pozwala na to typ narzędzia.",
    "info.inserts.title": "Głowice frezujące gwinty z płytką wymienną",
    "info.inserts.body": "Wybierz niestandardowe wymiary narzędzia i wprowadź średnicę skrawania korpusu freza, długość krawędzi skrawającej płytki oraz liczbę płytek. W razie potrzeby SmiProg wykonuje całą długość gwintu w kilku przejściach osiowych. Sprawdź wygenerowany program przed obróbką.",
    "info.taperedThreads.title": "Gwinty stożkowe",
    "info.taperedThreads.body": "W przypadku gwintów stożkowych średnica frezu odnosi się do ostatniego pełnego zwoju najbliżej chwytu. Aby uzyskać poprawny program CNC, wprowadź średnicę gwintu w tym miejscu.",
    "info.warning.title": "Ostrzeżenie",
    "info.warning.body": "Dane skrawania w SmiProg są zalecanymi wartościami początkowymi. Wiele czynników może wymagać ich korekty, między innymi materiał przedmiotu, stabilność maszyny, mocowanie, ustawienie narzędzia, chłodzenie i odprowadzanie wiórów. SmiCut nie ponosi odpowiedzialności za szkody wynikające z użycia programu CNC lub danych skrawania zalecanych przez oprogramowanie.",
    "materialSelector.welcomeTitle": "Jaki materiał chcesz obrabiać?",
    "materialSelector.welcomeDescription": "Wpisz oznaczenie lub nazwę materiału, a pomożemy Ci znaleźć właściwą kategorię materiału.",
    "materialSelector.findCategory": "Znajdź kategorię materiału",
    "materialSelector.placeholder": "Np. AISI 1045 lub EN 1.4301",
    "materialSelector.applyHelp": "Materiał zostanie użyty we frezowaniu gwintu i porównaniu.",
