    "tool.custom": "自定义刀具",
    "tool.linkText": "➜ 前往刀具页面查看所有尺寸及三维 STEP 文件",
    "info.howToUse": "如何使用 SmiProg",
    "info.step1.title": "定义螺纹",
    "info.step1.body": "选择材质、螺纹牙型、尺寸和螺纹长度。在 CNC 程序栏中输入安全距离。M 螺纹的螺距以毫米表示；其他牙型使用每英寸牙数（TPI）。",
    "info.step2.title": "选择螺纹铣刀",
    "info.step2.body": "使用建议的 SmiCut 刀具或在刀具选择中输入自定义刀具尺寸。",
    "info.step3.title": "检查输出",
    "info.step3.body": "在 CNC 程序中选择制造工艺、控制系统和螺纹旋向。在加工前检查切削数据、加工时间和 CNC 程序。",
    "info.beforeMachining.title": "加工前",
    "info.beforeMachining.body": "请确认所选螺纹铣刀能够加工该螺纹直径、螺距和螺纹长度。在运行生产前，请在仿真或单段模式下确认程序。",
    "info.figureAlt": "螺纹铣削尺寸图，显示螺纹直径、螺距、螺纹长度、刃长、安全距离和刀具直径。",
    "info.figure.threadDiameter": "螺纹直径",
    "info.figure.pitch": "螺距",
    "info.figure.threadLength": "螺纹长度",
    "info.figure.safetyDistance": "安全距离",
    "info.figure.cutterDiameter": "刀具直径",
    "info.figure.cuttingLength": "刃长",
    "info.machiningNotes": "加工注意事项",
    "info.toolCompensation.title": "刀具补偿",
    "info.toolCompensation.body": "在 SmiProg 中，刀具补偿仅用于微量调整。这样可减少短距离移动时采用半径补偿所引起的问题。因此，请在数控系统刀具表中使用接近零的刀具直径补偿值。",
    "info.correctThreadDiameter.title": "正确的螺纹直径",
    "info.correctThreadDiameter.body": "SmiCut 采用光学方法测量螺纹铣刀的螺纹中径，并将理论外径用激光标记在每把刀具上。请在 SmiProg 中将此数值输入为刀具直径，以便首次加工就获得正确的螺纹直径。如需进一步修正，可修改 SmiProg 中的数值，或调整数控系统中的刀具补偿。",
    "info.customTools.title": "非标刀具或表中未列出的刀具",
    "info.customTools.body": "如果刀具未列在表中，请在刀具选择中选择自定义刀具尺寸，并输入刀具直径、刃长和刃数。使用非标刀具时，请仔细检查生成的程序。",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "在螺纹长度栏中输入所选 SmiCut 整体硬质合金螺纹铣刀的全部刃长。这样即可使用 ThreadBurr 在同一工序中完成螺纹铣削和去毛刺。",
    "info.threadBurr.link": "ThreadBurr – 整体硬质合金螺纹铣刀",
    "info.oneTwoRows.title": "每刃有一个或两个牙（单牙或双牙）的螺纹铣刀",
    "info.oneTwoRows.body": "选择每刃有一个或两个牙的 SmiCut 标准 NM 型螺纹铣刀后，SmiProg 会自动生成螺旋路径，直至完成螺纹。若要用其他合适的刀具执行同样的循环，请在自定义刀具尺寸中将螺距输入为刃长。加工前请确认刀具适用，并检查生成的程序。",
    "info.flankInfeed.title": "侧向切入",
    "info.flankInfeed.body": "编程多次径向走刀时，SmiProg 采用沿牙侧方向切入的方式。这有助于减少振动并提高加工稳定性。",
    "info.flankInfeed.link": "Vibration-Free Thread Milling: Improving Productivity and Economy",
    "info.shortCuttingLength.title": "缩颈螺纹铣刀",
    "info.shortCuttingLength.body": "如果刀具刃长短于要求的螺纹长度，且刀具类型允许，SmiProg 会通过多次轴向走刀完成加工。",
    "info.inserts.title": "可转位螺纹铣刀",
    "info.inserts.body": "选择自定义刀具尺寸，输入刀体的切削直径、刀片的切削刃长度和刀片数量。需要时，SmiProg 会通过多次轴向走刀加工全部螺纹长度。加工前请检查生成的程序。",
    "info.taperedThreads.title": "锥形螺纹",
    "info.taperedThreads.body": "对于锥螺纹，铣刀直径以最靠近刀柄的最后一个完整牙型为基准。请填写该位置的螺纹直径，以生成正确的 CNC 程序。",
    "info.warning.title": "警告",
    "info.warning.body": "SmiProg 中的切削数据为推荐的初始数据。许多因素可能需要调整，包括工件材质、机床稳定性、夹具、刀具安装、冷却液及排屑情况。SmiCut 不对使用该软件推荐的 CNC 程序或切削数据造成的损坏承担责任。",
