    "tool.customDimensions": "➜ 自訂刀具尺寸",
    "tool.custom": "自訂刀具",
    "tool.linkText": "➜ 請參閱刀具頁面以取得所有尺寸與 3D STEP 檔案",
    "info.howToUse": "如何使用 SmiProg",
    "info.step1.title": "定義螺紋",
    "info.step1.body": "選取材質、螺紋牙型、尺寸與螺紋長度。請在 CNC 程式欄中輸入安全距離。M 螺紋的螺距以毫米表示；其他牙型使用每英吋牙數（TPI）。",
    "info.step2.title": "選取銑牙刀",
    "info.step2.body": "使用建議的 SmiCut 刀具，或在刀具選擇中輸入自訂刀具尺寸。",
    "info.step3.title": "檢查輸出",
    "info.step3.body": "在 CNC 程式中選取銑牙方式、控制系統和螺紋旋向。加工前請檢查切削數據、加工時間和 CNC 程式。",
    "info.beforeMachining.title": "加工前",
    "info.beforeMachining.body": "請確認所選的銑牙刀能加工該螺紋直徑、螺距與螺紋長度。在執行生產前，請於模擬或單節執行模式中確認程式。",
    "info.figureAlt": "銑牙加工尺寸圖，顯示螺紋直徑、螺距、螺紋長度、刃長、安全距離與刀具直徑。",
    "info.figure.threadDiameter": "螺紋直徑",
    "info.figure.pitch": "螺距",
    "info.figure.threadLength": "螺紋長度",
    "info.figure.safetyDistance": "安全距離",
    "info.figure.cutterDiameter": "刀具直徑",
    "info.figure.cuttingLength": "刃長",
    "info.machiningNotes": "加工注意事項",
    "info.toolCompensation.title": "刀具補償",
    "info.toolCompensation.body": "在 SmiProg 中，刀具補償僅用於微量調整。這可減少短距離移動時使用半徑補償所產生的問題。因此，請在控制系統的刀具表中使用接近零的刀具直徑補償值。",
    "info.correctThreadDiameter.title": "正確的螺紋直徑",
    "info.correctThreadDiameter.body": "SmiCut 以光學方式量測銑牙刀的螺紋中徑，並將理論外徑以雷射標記在每支刀具上。請在 SmiProg 中將此數值輸入為刀具直徑，以便首次加工就獲得正確的螺紋直徑。如需進一步修正，可修改 SmiProg 中的數值，或調整控制系統中的刀具補償。",
    "info.customTools.title": "清單以外及特殊刀具",
    "info.customTools.body": "若刀具不在清單中，請在刀具選擇中選取自訂刀具尺寸，並輸入刀具直徑、刃長與刃數。使用特殊刀具時，請仔細檢查產生的程式。",
    "info.threadBurr.title": "ThreadBurr",
    "info.threadBurr.body": "在螺紋長度欄輸入所選 SmiCut 全鎢鋼銑牙刀的完整刃長。如此即可使用 ThreadBurr 在同一工序中完成銑牙及去毛邊。",
    "info.threadBurr.link": "ThreadBurr-全鎢鋼銑牙刀",
    "info.oneTwoRows.title": "以每刃一或二牙銑牙",
    "info.oneTwoRows.body": "選用每刃一牙或二牙的 SmiCut 標準 NM 型銑牙刀時，SmiProg 會自動產生螺旋路徑，直到完成螺紋。若要用其他合適的刀具執行相同循環，請在自訂刀具尺寸中將螺距輸入為刃長。加工前請確認刀具適用，並檢查產生的程式。",
    "info.flankInfeed.title": "側向切入",
    "info.flankInfeed.body": "編寫多次徑向進刀的程式時，SmiProg 採用沿牙側方向切入的方式。這有助於減少振動並提高加工穩定性。",
    "info.flankInfeed.link": "抗震銑牙加工：提升產能以及經濟性",
    "info.shortCuttingLength.title": "縮頸銑牙刀",
    "info.shortCuttingLength.body": "如果刀具刃長短於要求的螺紋長度，且刀具類型允許，SmiProg 會透過多次軸向進刀完成加工。",
    "info.inserts.title": "可換刀片式銑牙刀",
    "info.inserts.body": "選取自訂刀具尺寸，輸入刀體的切削直徑、刀片的刃長與刀片數量。需要時，SmiProg 會透過多次軸向進刀完成整個螺紋長度。加工前請檢查產生的程式。",
    "info.taperedThreads.title": "錐度銑牙",
    "info.taperedThreads.body": "對於錐螺紋，銑刀直徑以最靠近刀柄的最後一個完整牙型為基準。請輸入該位置的螺紋直徑，以產生正確的 CNC 程式。",
    "info.warning.title": "警告",
    "info.warning.body": "SmiProg 中的切削資料為建議起始值。許多因素可能需要調整，包括工件材質、機床穩定性、夾具、刀具設定、冷卻液及切屑排除。SmiCut 不對使用該軟體建議的 CNC 程式或切削資料所造成的損壞負責。",
